  // ---------- tema ----------
  var THEMES = { 'BlueGrey': '#607D8B', 'Indigo': '#3F51B5', 'Teal': '#009688', 'DeepPurple': '#673AB7', 'Green': '#4CAF50', 'Amber': '#FFA000', 'Red': '#E53935', 'Pink': '#D81B60' };
